[
  {
    "statement": "Creating pit habitats between 1 and 50 millimeters on intertidal artificial structures appears to be the most well-studied and effective method for enhancing biodiversity.",
    "citations": []
  },
  {
    "statement": "Studies have shown that creating pit habitats increased the combined richness and/or diversity of macroalgae and invertebrate species on structure surfaces.",
    "citations": [
      "3475"
    ]
  },
  {
    "statement": "The pit habitats supported macroalgae, invertebrate, and fish species that were absent from structure surfaces without these added habitats.",
    "citations": []
  },
  {
    "statement": "Creating small protrusions between 1 and 50 millimeters also shows promise for enhancing biodiversity.",
    "citations": []
  },
  {
    "statement": "Two studies in Singapore found that adding small protrusions, when combined with grooves, small ridges, and pits, resulted in increased species richness.",
    "citations": [
      "3462"
    ]
  },
  {
    "statement": "Creating large ridges or ledges greater than 50 millimeters demonstrated effectiveness in three studies.",
    "citations": []
  },
  {
    "statement": "One study reported that adding large ridges or ledges increased species diversity when combined with grooves and small protrusions.",
    "citations": [
      "3465"
    ]
  },
  {
    "statement": "Reducing the slope of intertidal artificial structures showed mixed results for enhancing biodiversity.",
    "citations": []
  },
  {
    "statement": "One study found that reducing the slope of a structure, when combined with creating rock pools, increased the combined species richness of macroalgae, invertebrates, and fish.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Using environmentally-sensitive materials had varied effects on biodiversity across eight studies.",
    "citations": []
  },
  {
    "statement": "Some materials, like ECOncrete™, showed benefits when combined with creating grooves, small ledges, and holes.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Other environmentally-sensitive materials showed mixed or no effects on biodiversity.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Creating flexible habitats showed limited effectiveness for enhancing biodiversity.",
    "citations": []
  },
  {
    "statement": "One study found that short flexible habitats between 1 and 50 millimeters decreased species richness.",
    "citations": [
      "3459"
    ]
  },
  {
    "statement": "One study found that long flexible habitats greater than 50 millimeters altered community composition.",
    "citations": [
      "3460"
    ]
  }
]

[
  {
    "statement": "No studies were found that directly evaluated the effects of creating crevice habitats larger than 50 mm on subtidal artificial structures on fish abundance.",
    "citations": [
      "3454"
    ]
  },
  {
    "statement": "Related research on hole habitats larger than 50 mm on subtidal artificial structures showed mixed effects on fish abundance.",
    "citations": []
  },
  {
    "statement": "Two studies found that creating hole habitats on subtidal artificial structures did not increase fish species abundances on and around the structures.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "One study reported that creating hole habitats on subtidal artificial structures had mixed effects on fish abundances depending on the species group.",
    "citations": [
      "3434"
    ]
  },
  {
    "statement": "Studies on groove habitats between 1 and 50 mm on subtidal artificial structures found mixed effects on fish abundances.",
    "citations": [
      "3448"
    ]
  },
  {
    "statement": "The effects on fish abundances from groove habitats depended on the species group.",
    "citations": [
      "3448"
    ]
  },
  {
    "statement": "Research on artificial reefs of different 3-D structure and materials found no differences in the combined abundance of mobile invertebrates and fish.",
    "citations": [
      "2259"
    ]
  }
]

[
  {
    "statement": "There are no studies that evaluate the effects of creating large protrusions on subtidal artificial structures on marine mammal populations specifically.",
    "citations": []
  },
  {
    "statement": "No studies were found that evaluated the effects of creating large protrusions on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "There are no available studies evaluating the effects of creating crevice habitats on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3454"
    ]
  },
  {
    "statement": "There are no available studies evaluating the effects of creating large ridges or ledges on the biodiversity of subtidal artificial structures.",
    "citations": [
      "3445"
    ]
  },
  {
    "statement": "There are no available studies evaluating the effects of reducing the slope of subtidal artificial structures on biodiversity.",
    "citations": [
      "3442"
    ]
  },
  {
    "statement": "Documents that address eco-engineering on artificial structures focus primarily on effects on macroalgae, invertebrates, and fish communities.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Studies on environmentally-sensitive materials examined community composition and abundance of macroalgae, invertebrates, and fish.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Studies on environmentally-sensitive materials make no specific mention of marine mammal interactions or effects.",
    "citations": [
      "3470"
    ]
  }
]

[
  {
    "statement": "No studies were found that specifically evaluated public perceptions of reducing the slope of intertidal artificial structures for biodiversity enhancement.",
    "citations": []
  },
  {
    "statement": "The action documents focus primarily on the scientific and ecological effects of reducing the slope of intertidal artificial structures.",
    "citations": []
  },
  {
    "statement": "Two studies from southeast Australia examined the biological effects of reducing slopes on intertidal artificial structures.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "One study reported increased combined macroalgae, invertebrate and fish species richness when slope reduction was combined with creating rock pools.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "Another study found no increase in macroalgal abundance or oyster and mobile invertebrate abundance from slope reduction alone.",
    "citations": [
      "3461"
    ]
  },
  {
    "statement": "None of the available action documents contain information about stakeholder views, public acceptance, social attitudes, or community perceptions regarding reducing the slope of intertidal artificial structures as a biodiversity enhancement measure.",
    "citations": []
  }
]

[
  {
    "statement": "Using environmentally-sensitive material on subtidal artificial structures shows the most promise for increasing biodiversity.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Using shell-concrete or quarried rock in place of standard-concrete on subtidal artificial structures altered the combined macroalgae and invertebrate community composition on structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Using ECOncrete™ in place of standard-concrete or fibreglass, along with creating texture, grooves, holes, pits and/or small ledges, altered the combined macroalgae and invertebrate community composition on structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "ECOncrete™ surfaces with added habitats supported mobile invertebrate, non-mobile invertebrate and/or fish species that were absent from standard-concrete or fibreglass structure surfaces.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Using ECOncrete™, along with creating texture, grooves, holes, pits and/or small ledges, did increase the species diversity and/or richness on and around structures.",
    "citations": [
      "3470"
    ]
  },
  {
    "statement": "Managing or restricting harvesting showed some benefits for biodiversity.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "Higher fish species richness was found around a subtidal artificial structure with harvesting restrictions compared with unrestricted structures.",
    "citations": [
      "3457"
    ]
  },
  {
    "statement": "Creating short flexible habitats had mixed effects on invertebrate communities depending on density, length and site.",
    "citations": [
      "3450"
    ]
  },
  {
    "statement": "Reducing slopes as a method for increasing biodiversity showed no evidence or mixed results.",
    "citations": [
      "3442"
    ]
  },
  {
    "statement": "Creating large protrusions as a method for increasing biodiversity showed no evidence or mixed results.",
    "citations": [
      "3443"
    ]
  },
  {
    "statement": "Creating natural rocky reef topography as a method for increasing biodiversity showed no evidence or mixed results.",
    "citations": [
      "3446"
    ]
  }
]

[
  {
    "statement": "No studies have been found that directly evaluated the effects of creating crevice habitats (>50 mm) on the biodiversity of intertidal artificial structures.",
    "citations": [
      "3437"
    ]
  },
  {
    "statement": "Studies of habitat features similar to crevice habitats provide related insights.",
    "citations": []
  },
  {
    "statement": "Studies in South Africa, the UK and Netherlands found that small adjoining cavities or 'swimthrough' habitats (≤100 mm) did not alter mobile invertebrate community composition on structure surfaces.",
    "citations": [
      "3468"
    ]
  },
  {
    "statement": "Small adjoining cavities or 'swimthrough' habitats (≤100 mm) did not increase mobile invertebrate species richness or diversity on structure surfaces.",
    "citations": [
      "3468"
    ]
  },
  {
    "statement": "Small adjoining cavities or 'swimthrough' habitats (≤100 mm) did increase mobile invertebrate abundance on structure surfaces.",
    "citations": [
      "3468"
    ]
  },
  {
    "statement": "Studies in Australia, the UK, Israel and the Netherlands found that holes (>50 mm), when combined with other features like grooves and small ridges, altered macroalgae and invertebrate community composition.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Hole habitats (>50 mm), when combined with other features, supported species absent from surfaces without habitat features.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Hole habitats (>50 mm), when combined with other features, increased combined macroalgae and invertebrate species diversity and richness on structure surfaces.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "The effects of hole habitats (>50 mm) on individual invertebrate abundance were mixed.",
    "citations": [
      "3467"
    ]
  },
  {
    "statement": "Studies across multiple locations on groove habitats (1-50 mm) found mixed results.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "Some studies showed that groove habitats supported macroalgae, mobile and non-mobile invertebrate species absent from surfaces without grooves.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "In some cases, groove habitats increased combined macroalgae and invertebrate species richness and diversity.",
    "citations": [
      "3473"
    ]
  },
  {
    "statement": "The effects of groove habitats varied by site and groove configuration.",
    "citations": [
      "3473"
    ]
  }
]

[
  {
    "statement": "Information specifically addressing the impact of rock pool creation on the long-term structural integrity of engineering materials is limited.",
    "citations": []
  },
  {
    "statement": "Eighteen studies that examined the effects of creating rock pools focused primarily on biodiversity outcomes rather than structural integrity impacts.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "Rock pools created on intertidal artificial structures supported various species including macroalgae, mobile invertebrates, non-mobile invertebrates, and fish.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "The species found in rock pools were absent from structure surfaces without pools.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "One study mentioned that wave-sheltered pools filled with sediment within two years.",
    "citations": [
      "3476"
    ]
  },
  {
    "statement": "The use of environmentally-sensitive materials on intertidal artificial structures includes various concrete compositions and alternative materials like sandstone and limestone.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "Available information on environmentally-sensitive materials does not specifically address structural integrity concerns related to habitat modifications.",
    "citations": [
      "3469"
    ]
  },
  {
    "statement": "The available documents do not contain specific information about how the creation of rock pools affects material durability of seawalls over time.",
    "citations": []
  },
  {
    "statement": "The available documents do not contain specific information about how the creation of rock pools affects erosion rates of seawalls over time.",
    "citations": []
  },
  {
    "statement": "The available documents do not contain specific information about how the creation of rock pools affects the structural stability of seawalls over time.",
    "citations": []
  },
  {
    "statement": "The available documents do not contain specific information about how the creation of rock pools affects other engineering performance parameters of seawalls over time.",
    "citations": []
  }
]

[
  {
    "statement": "Based on evidence from subtidal artificial structures, creating textured surfaces shows mixed results for increasing invertebrate abundance.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "Based on evidence from subtidal artificial structures, transplanting organisms shows mixed results for increasing invertebrate abundance.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "One replicated, randomized, controlled study in Italy found that creating textured surfaces (≤1 mm) had mixed effects on non-mobile invertebrate abundance on structure surfaces, depending on the site.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "Two of three replicated, controlled studies found that creating textured surfaces did not increase the combined macroalgae and non-mobile invertebrate live cover on structure surfaces.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "One study found that textured surfaces combined with environmentally-sensitive material did increase cover and biomass.",
    "citations": [
      "3449"
    ]
  },
  {
    "statement": "A replicated, randomized, controlled and site comparison study in Australia found that transplanting sea urchins onto a subtidal artificial structure reduced the cover of non-native sea mat on kelps.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "A study in Singapore reported that transplanting corals increased coral cover on structure surfaces.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "One study found that transplanting oysters did not increase the combined invertebrate and fish abundance on and around structure surfaces.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "The effects of transplanting oysters on abundance varied for different species.",
    "citations": [
      "3471"
    ]
  },
  {
    "statement": "Neither creating textured surfaces nor transplanting organisms shows consistently superior effectiveness for increasing overall invertebrate abundance.",
    "citations": []
  },
  {
    "statement": "The results for increasing overall invertebrate abundance vary by site, species, and study conditions.",
    "citations": []
  }
]
